"""Cron-style schedules. SCHEDULE.md has the full rules."""
import calendar
import datetime as _dt
import re

_SHORTCUTS = {
    "@yearly": "0 0 1 1 *",
    "@annually": "0 0 1 1 *",
    "@monthly": "0 0 1 * *",
    "@weekly": "0 0 * * 0",
    "@daily": "0 0 * * *",
    "@midnight": "0 0 * * *",
    "@hourly": "0 * * * *",
}
_MONTHS = ["jan", "feb", "mar", "apr", "may", "jun",
           "jul", "aug", "sep", "oct", "nov", "dec"]
_DAYS = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"]
_MONTH_NAMES = {name: i + 1 for i, name in enumerate(_MONTHS)}
_DAY_NAMES = {name: i for i, name in enumerate(_DAYS)}

# (minimum, maximum, names) per field; day of week allows 7 as well as 0 for Sunday.
_FIELDS = [
    (0, 59, None),
    (0, 23, None),
    (1, 31, None),
    (1, 12, _MONTH_NAMES),
    (0, 7, _DAY_NAMES),
]
_MINUTE, _HOUR, _DOM, _MONTH, _DOW = range(5)
_NUMBER = re.compile(r"[0-9]+")
_LIMIT = _dt.timedelta(days=10 * 365)


def _value(token, index):
    """One field value, from a number or (where allowed) a name."""
    low, high, names = _FIELDS[index]
    if _NUMBER.fullmatch(token):
        n = int(token)
    elif names is not None and token.lower() in names:
        n = names[token.lower()]
    else:
        raise ValueError(f"bad value {token!r}")
    if not low <= n <= high:
        raise ValueError(f"value {token!r} out of range")
    return n


def _range(token, index):
    """Values listed by '*', 'N' or 'A-B' (before any step), in order."""
    low, high, _ = _FIELDS[index]
    if token == "*":
        return list(range(low, high + 1))
    if "-" in token:
        a_text, b_text = token.split("-", 1)
        if not a_text or not b_text:
            raise ValueError(f"bad range {token!r}")
        a, b = _value(a_text, index), _value(b_text, index)
        if index == _DOW:
            if a == 7:
                a = 0
            if a > b:
                # Wraps through 0-6 with 7 treated as 0.
                return list(range(a, 7)) + list(range(0, b + 1))
            return list(range(a, b + 1))
        if a > b:
            return list(range(a, high + 1)) + list(range(low, b + 1))
        return list(range(a, b + 1))
    return [_value(token, index)]


def _item(token, index, parsed):
    """Add one comma-separated item to parsed, a dict describing the field."""
    if not token:
        raise ValueError("empty item")
    upper = token.upper()
    if index == _DOM and upper == "L":
        parsed["last_dom"] = True
        return
    if index == _DOW:
        if upper.endswith("L") and _NUMBER.fullmatch(token[:-1] or "x"):
            n = _value(token[:-1], _DOW)
            parsed["last_dow"].add(n % 7)
            return
        if "#" in token:
            n_text, k_text = token.split("#", 1)
            if not (_NUMBER.fullmatch(n_text) and _NUMBER.fullmatch(k_text)):
                raise ValueError(f"bad item {token!r}")
            n, k = _value(n_text, _DOW), int(k_text)
            if not 1 <= k <= 5:
                raise ValueError(f"bad week number in {token!r}")
            parsed["nth_dow"].add((n % 7, k))
            return
    step = 1
    if "/" in token:
        token, step_text = token.split("/", 1)
        if not _NUMBER.fullmatch(step_text):
            raise ValueError(f"bad step {step_text!r}")
        step = int(step_text)
        if step < 1:
            raise ValueError("step must be at least 1")
        if token != "*" and "-" not in token:
            # N/S lists N up to the field's maximum.
            low, high, _ = _FIELDS[index]
            values = list(range(_value(token, index), high + 1))
        else:
            values = _range(token, index)
    else:
        values = _range(token, index)
    values = values[::step]
    if index == _DOW:
        values = [v % 7 for v in values]
    parsed["values"].update(values)


def _field(text, index):
    parsed = {"values": set(), "last_dom": False, "last_dow": set(), "nth_dow": set(),
              "restricted": True}
    if text == "*" or (text == "?" and index in (_DOM, _DOW)):
        parsed["restricted"] = False
        low, high, _ = _FIELDS[index]
        parsed["values"] = set(range(low, high + 1))
        return parsed
    for token in text.split(","):
        _item(token, index, parsed)
    return parsed


def _parse(expr):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    text = expr.strip()
    if text.startswith("@"):
        try:
            text = _SHORTCUTS[text.lower()]
        except KeyError:
            raise ValueError(f"unknown shortcut {text!r}") from None
    parts = text.split()
    if len(parts) != 5:
        raise ValueError(f"expected 5 fields, got {len(parts)}")
    return [_field(part, i) for i, part in enumerate(parts)]


def _day_allowed(fields, year, month, day):
    dom, dow = fields[_DOM], fields[_DOW]
    if not dom["restricted"] and not dow["restricted"]:
        return True
    days_in_month = calendar.monthrange(year, month)[1]
    weekday = (calendar.weekday(year, month, day) + 1) % 7  # Sunday is 0

    dom_ok = day in dom["values"] or (dom["last_dom"] and day == days_in_month)
    dow_ok = (weekday in dow["values"]
              or (weekday in dow["last_dow"] and day + 7 > days_in_month)
              or (weekday, (day - 1) // 7 + 1) in dow["nth_dow"])

    if dom["restricted"] and dow["restricted"]:
        return dom_ok or dow_ok
    return dom_ok if dom["restricted"] else dow_ok


def matches(expr, when):
    """True if the schedule expr runs at the minute of the datetime when."""
    fields = _parse(expr)
    return (when.minute in fields[_MINUTE]["values"]
            and when.hour in fields[_HOUR]["values"]
            and when.month in fields[_MONTH]["values"]
            and _day_allowed(fields, when.year, when.month, when.day))


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    fields = _parse(expr)
    minutes = sorted(fields[_MINUTE]["values"])
    hours = sorted(fields[_HOUR]["values"])
    months = fields[_MONTH]["values"]
    limit = after + _LIMIT

    start = after.replace(second=0, microsecond=0) + _dt.timedelta(minutes=1)
    day = start.date()
    first_day = True
    while True:
        if _dt.datetime.combine(day, _dt.time(hours[0], minutes[0])) > limit:
            return None
        if day.month in months and _day_allowed(fields, day.year, day.month, day.day):
            for hour in hours:
                if first_day and hour < start.hour:
                    continue
                for minute in minutes:
                    if first_day and hour == start.hour and minute < start.minute:
                        continue
                    run = _dt.datetime.combine(day, _dt.time(hour, minute))
                    if run > limit:
                        return None
                    return run
        first_day = False
        day += _dt.timedelta(days=1)
